/**
 * Re-exports Rust-generated TypeScript IPC types (`ts-rs`).
 *
 * Ownership:
 * - Rust backend (`src-tauri/src/herdr/types.rs`, `commands.rs`, `config_runtime.rs`)
 *   is the single source of truth for JSON IPC payloads.
 * - `src-tauri/bindings/ipc.ts` is generated by `ts-rs` and drift-checked by
 *   `cargo test --lib ipc_bindings_are_current`.
 * - `src/ipc/types.ts` re-exports these types alongside TypeScript-side binary
 *   frame helpers (`decodeOutputFrame`) and `UitermBackendClient`.
 */
export type {
  ConfigEvalParams,
  ConfigEvalResult,
  CoreEvent,
  CoreStatus,
  DisplayFacts,
  EventDelivery,
  EventsSubscribeResult,
  ForegroundProcess,
  IpcError,
  StatusRecord,
  TerminalAttachParams,
  TerminalAttachResult,
  TerminalCreateParams,
  TerminalInfo,
} from "../../../src-tauri/bindings/ipc.ts";
